from typing import Annotated
from fastapi import Depends, FastAPI
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from fastapi.testclient import TestClient

app = FastAPI()
security = HTTPBearer()

@app.get("/users/me")
def read_current_user(
    credentials: Annotated[HTTPAuthorizationCredentials, Depends(security)]
):
    return {"scheme": credentials.scheme, "credentials": credentials.credentials}

client = TestClient(app)

def test_authorization_header():
    # Test case 1: Single space (correct)
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx"})
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 2: Multiple spaces
    response = client.get("/users/me", headers={"Authorization": "Bearer   xxx"})
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 3: Trailing whitespace
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx "})
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

    print("All tests passed!")

if __name__ == "__main__":
    try:
        test_authorization_header()
    except AssertionError as e:
        print(f"Assertion failed: {e}")
        import sys
        sys.exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        import sys
        sys.exit(1)

steps.message:
The issue was that the `Authorization` header credentials were not being stripped of leading and trailing whitespace, which violated RFC 6750 and could lead to authentication failures.

I modified `fastapi/security/utils.py` in the `get_authorization_scheme_param` function to call `.strip()` on the extracted parameter.

```python
def get_authorization_scheme_param(
    authorization_header_value: Optional[str],
) -> tuple[str, str]:
    if not authorization_header_value:
        return "", ""
    scheme, _, param = authorization_header_value.partition(" ")
    return scheme, param.strip()
```

I verified the fix with a reproduction script that tested single space, multiple spaces, and trailing whitespace in the `Authorization` header, all of which now correctly return the stripped credentials.
